import {openStaticSettings} from './settings-entry.js';
import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import * as ts from 'typescript/unstable/ast';
import {withParsedSource} from '../../scripts/native-typescript-ast.js';
import {performance as hostPerformance} from 'node:perf_hooks';
import {devices, expect, test} from '@playwright/test';
import {startKitServer} from './kit-server.js';

const artifact = path.resolve(process.env.GETBASED_KIT_ARTIFACT || '.local-notes/sveltekit-build');
const pixel = devices['Pixel 5'];
const modes = [
  {name: 'desktop', use: {viewport: {width: 1440, height: 1000}, isMobile: false, hasTouch: false, deviceScaleFactor: 1}},
  {name: 'Pixel 5', use: {viewport: pixel.viewport, userAgent: pixel.userAgent,
    deviceScaleFactor: pixel.deviceScaleFactor, isMobile: pixel.isMobile, hasTouch: pixel.hasTouch}},
];
interface StartupObservation {
  readyMs: number | null;
  lcpMs: number | null;
  longTasks: {startMs: number; durationMs: number}[];
}

// These two executable helpers are generated by the pinned bundler, not authored
// modules. Unknown or changed executable code must provide a genuine source map.
const unmappedFrameworkBodies = new Map([
  ['49e31bba082196935782ac14bbedbc2a8e7c4229f918bc086ab5dd08ca015034', 'Vite CSS/module preload helper'],
  ['a526d1bb3288ef04d001028843220a24b0867a4edf8c685b69506d6525af36ff', 'Rolldown module export helper'],
]);
function unmappedGeneratedScript(code: string, url: URL, scripts: string[]) {
  const sha256 = createHash('sha256').update(code).digest('hex');
  const frameworkBody = unmappedFrameworkBodies.get(sha256);
  if (frameworkBody) return {url: url.pathname, kind: frameworkBody, sha256, imports: [] as string[]};
  const imports = withParsedSource(code, url.pathname, (file, project) => {
    expect(project.program.getSyntacticDiagnostics(), `unmapped script syntax: ${url.pathname}`).toEqual([]);
    expect(file.statements.length).toBeGreaterThan(0);
    const dependencies: string[] = [];
    for (const statement of file.statements) {
      if (!ts.isImportDeclaration(statement) && !ts.isExportDeclaration(statement)) {
        throw new Error(`Unmapped optimized script contains executable code: ${url.pathname}`);
      }
      const specifier = statement.moduleSpecifier;
      if (!specifier) continue; // Named exports may forward the imported bindings.
      if (!ts.isStringLiteral(specifier)) throw new Error(`Nonliteral barrel dependency: ${url.pathname}`);
      const dependency = new URL(specifier.text, url);
      expect(dependency.origin).toBe(url.origin);
      expect(dependency.pathname).toMatch(/^\/_app\/immutable\/chunks\/[A-Za-z0-9_-]+\.js$/);
      expect(dependency.search).toBe(''); expect(dependency.hash).toBe('');
      expect(scripts, `barrel dependency must have actually loaded: ${dependency.href}`).toContain(dependency.href);
      dependencies.push(dependency.pathname);
    }
    expect(dependencies.length, 'A forwarding barrel must have real loaded dependencies').toBeGreaterThan(0);
    return [...new Set(dependencies)];
  });
  return {url: url.pathname, kind: 'AST-verified import/export-only barrel', sha256, imports};
}

// Inspect maps on the host after measuring startup: fetching diagnostic maps in
// the browser would change its request/byte totals and network-idle observation.
async function loadedSources(urls: string[], origin: string) {
  const scripts = [...new Set(urls.filter(value => {
    const url = new URL(value);
    return url.origin === origin && /\.m?js$/.test(url.pathname);
  }))];
  const sources = new Set<string>();
  const maps: string[] = [];
  const generatedHelpers: ReturnType<typeof unmappedGeneratedScript>[] = [];
  const rawScripts: {url: string; declaredSourceMap: string | null; sourceMapShipped: boolean}[] = [];
  function publicFile(url: URL) {
    expect(url.origin).toBe(origin);
    const file = path.resolve(artifact, '.' + decodeURIComponent(url.pathname));
    expect(file.startsWith(artifact + path.sep)).toBe(true);
    return file;
  }
  for (const script of scripts) {
    const url = new URL(script);
    sources.add(url.pathname);
    const code = await fs.readFile(publicFile(url), 'utf8');
    // Only the real terminal directive describes this script. Compatibility
    // renderers can contain unrelated sourceMappingURL text in their payloads.
    const mapReference = code.match(/(?:^|\r?\n)\/\/# sourceMappingURL=(\S+)[\t ]*(?:\r?\n)?$/)?.[1];
    if (!url.pathname.startsWith('/_app/')) {
      // Raw compatibility scripts ship through the worker roster; their compiler
      // map siblings have never been a public-artifact contract. Record this
      // explicitly, while retaining every raw URL in the vendor assertion.
      const mapUrl = mapReference ? new URL(mapReference, url) : null;
      let sourceMapShipped = false;
      if (mapUrl) {
        try {await fs.access(publicFile(mapUrl)); sourceMapShipped = true;}
        catch (error) {if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;}
      }
      rawScripts.push({url: url.pathname, declaredSourceMap: mapUrl?.pathname ?? null, sourceMapShipped});
      continue;
    }
    if (!mapReference) {
      const helper = unmappedGeneratedScript(code, url, scripts);
      generatedHelpers.push(helper);
      for (const dependency of helper.imports) sources.add(dependency);
      continue;
    }
    const mapUrl = new URL(mapReference, url);
    const map = JSON.parse(await fs.readFile(publicFile(mapUrl), 'utf8')) as {sources?: unknown};
    expect(Array.isArray(map.sources), `source inventory: ${mapUrl.pathname}`).toBe(true);
    for (const source of map.sources as unknown[]) {
      expect(typeof source).toBe('string');
      sources.add((source as string).replaceAll('\\', '/'));
    }
    maps.push(mapUrl.pathname);
  }
  // A missing bundle map must fail rather than make the provider assertion vacuous.
  expect(maps.some(file => file.startsWith('/_app/'))).toBe(true);
  return {scripts, rawScripts, generatedHelpers, maps, sources: [...sources].sort()};
}

for (const mode of modes) test.describe(`static cold startup: ${mode.name}`, () => {
  test.use({...mode.use, serviceWorkers: 'block'});
  test.skip(({browserName}) => browserName !== 'chromium', 'CDP startup diagnostics are Chromium-specific');
  test('defers Settings CSS and optional attestation vendors until needed', async ({page, context}, testInfo) => {
    const server = await startKitServer(artifact);
    const errors: string[] = [];
    const externalRequests: string[] = [];
    page.on('pageerror', error => errors.push(error.message));
    await context.route('**/*', async route => {
      if (new URL(route.request().url()).origin === server.origin) await route.continue();
      else {externalRequests.push(route.request().url()); await route.abort();}
    });
    await context.addInitScript(() => {
      performance.setResourceTimingBufferSize(4000);
      localStorage.setItem('labcharts-legal-acceptance', JSON.stringify({accepted: true,
        termsVersion: '2026-08-22', privacyVersion: '2026-08-22', policyScope: 'self-hosted-notice',
        acceptedAt: '2026-07-23T00:00:00.000Z', appVersion: 'performance-audit', location: 'performance-audit'}));
      for (const [key, value] of Object.entries({'labcharts-default-onboarded': 'profile-set',
        'labcharts-default-emptyTour': 'completed', 'labcharts-default-tour': 'completed',
        'labcharts-default-ai-reminder-dismissed': '1', 'labcharts-onboard-extras-done-default': '1',
        'labcharts-onboard-provider-skipped-default': '1', 'labcharts-analytics-consent-seen': '1'})) localStorage.setItem(key, value);
      const observation: StartupObservation = {readyMs: null, lcpMs: null, longTasks: []};
      (window as Window & {startupObservation?: StartupObservation}).startupObservation = observation;
      const ready = new MutationObserver(() => {
        if (observation.readyMs === null && document.documentElement?.matches('html[data-app-ready][data-shell-framework="sveltekit"]')) {
          observation.readyMs = performance.now(); ready.disconnect();
        }
      });
      ready.observe(document, {subtree: true, attributes: true, attributeFilter: ['data-app-ready', 'data-shell-framework']});
      new PerformanceObserver(list => {
        for (const entry of list.getEntries()) observation.lcpMs = entry.startTime;
      }).observe({type: 'largest-contentful-paint', buffered: true});
      new PerformanceObserver(list => {
        for (const entry of list.getEntries()) observation.longTasks.push({startMs: entry.startTime, durationMs: entry.duration});
      }).observe({type: 'longtask', buffered: true});
    });
    const client = await context.newCDPSession(page);
    try {
      await client.send('Network.enable');
      await client.send('Network.setCacheDisabled', {cacheDisabled: true});
      await client.send('Performance.enable');
      const startedAt = hostPerformance.now();
      await page.goto(server.origin + '/app?dev-sw=1', {waitUntil: 'commit'});
      await expect(page.locator('html[data-app-ready][data-shell-framework="sveltekit"]')).toBeAttached({timeout: 30_000});
      const hostNavigationToReadyMs = hostPerformance.now() - startedAt;
      await page.waitForLoadState('networkidle');
      const timing = await page.evaluate(() => ({
        observation: (window as Window & {startupObservation?: StartupObservation}).startupObservation!,
        navigation: performance.getEntriesByType('navigation').map(entry => entry.toJSON()),
        resources: (performance.getEntriesByType('resource') as PerformanceResourceTiming[]).map(entry => ({...entry.toJSON(), name: entry.name})),
        paints: performance.getEntriesByType('paint').map(entry => entry.toJSON()),
        sampledAtMs: performance.now(),
      }));
      const metrics = (await client.send('Performance.getMetrics')).metrics;
      const inventory = await loadedSources(timing.resources.map(entry => entry.name), server.origin);
      await testInfo.attach('startup-performance.json', {body: JSON.stringify({
        conditions: {mode: mode.name, samples: 1, headless: true, freshContext: true, serviceWorkers: 'blocked',
          browserCache: 'disabled with CDP', externalNetwork: 'aborted', transport: 'local uncompressed HTTP',
          cpuThrottling: 'none', networkThrottling: 'none', capture: 'app-ready then networkidle',
          limitation: 'Local diagnostic readiness; excludes service-worker precaching and installed-PWA acceptance. No hardware timing thresholds.'},
        hostNavigationToReadyMs, timing, metrics,
        scriptDurationMs: 1000 * (metrics.find(metric => metric.name === 'ScriptDuration')?.value ?? 0),
        layoutDurationMs: 1000 * (metrics.find(metric => metric.name === 'LayoutDuration')?.value ?? 0),
        inventory, externalRequests, errors,
      }, null, 2), contentType: 'application/json'});
      expect(errors).toEqual([]);
      expect(timing.observation.readyMs).not.toBeNull();
      expect(timing.navigation).toHaveLength(1);
      expect(timing.resources.some(entry => new URL(entry.name).pathname === '/css/settings.css')).toBe(false);
      await expect(page.locator('link[data-settings-stylesheet]')).toHaveCount(0);
      const optionalVendors = /(?:^|\/)(?:vendor|vendor-entries)\/(?:tinfoil-browser|venice-(?:dcap|nvidia|e2ee))\.(?:js|ts)$/;
      expect(inventory.sources.filter(source => optionalVendors.test(source))).toEqual([]);

      // Exercise the real deferred consumer once; preserve the original document.
      const documentToken = await page.evaluate(() => {
        const token = String(performance.timeOrigin);
        (window as Window & {startupDocumentToken?: string}).startupDocumentToken = token;
        return token;
      });
      let navigations = 0;
      page.on('framenavigated', frame => {if (frame === page.mainFrame()) navigations++;});
      await openStaticSettings(page);
      await page.locator('[data-settings-tab="display"]').click();
      const stylesheet = page.locator('link[data-settings-stylesheet]');
      await expect(stylesheet).toHaveAttribute('href', server.origin + '/css/settings.css');
      await expect.poll(() => stylesheet.evaluate(link => !!(link as HTMLLinkElement).sheet)).toBe(true);
      const us = page.locator('#settings-tab-display [data-unit="US"]');
      const si = page.locator('#settings-tab-display [data-unit="EU"]');
      const next = await us.getAttribute('aria-pressed') === 'true' ? si : us;
      await expect(next).toHaveAttribute('aria-pressed', 'false');
      await next.click();
      await expect(next).toHaveAttribute('aria-pressed', 'true');
      expect(await page.evaluate(() => (window as Window & {startupDocumentToken?: string}).startupDocumentToken)).toBe(documentToken);
      expect(navigations).toBe(0);
      expect(errors).toEqual([]);
    } finally {await client.detach(); await server.close();}
  });
});
